const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const cfg=window.MUGHAL_CONFIG||{};
const cloud=Boolean(cfg.supabaseUrl&&cfg.supabasePublishableKey);
const state={token:null,userId:null,businessId:null,business:null,role:'owner',parties:[],projects:[],entries:[],invoices:[],paymentAccounts:[],payments:[],labourers:[],labourAssignments:[],materials:[],materialMovements:[],expenseCategories:[],walkInOrders:[],walkInEntries:[],orderItems:[],orderInvoiceItems:[],detail:null};
const today=()=>new Date().toISOString().slice(0,10);
const uid=()=>crypto.randomUUID();
const esc=(value='')=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const money=value=>`Rs. ${Number(value||0).toLocaleString('en-PK',{maximumFractionDigits:2})}`;
const qty=value=>Number(value||0).toLocaleString('en-PK',{maximumFractionDigits:3});
const date=value=>value?new Date(`${String(value).slice(0,10)}T00:00:00`).toLocaleDateString('en-PK',{day:'numeric',month:'short',year:'numeric'}):'Not set';
const daysBetween=(start,end)=>start&&end?Math.max(0,Math.round((new Date(`${end}T00:00:00`)-new Date(`${start}T00:00:00`))/86400000)):'';
const shortCode=(prefix,value)=>`${prefix}-${String(value||'NEW').replaceAll('-','').slice(0,8).toUpperCase()}`;
const safeName=value=>String(value||'document').replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'').toLowerCase();
const party=id=>state.parties.find(row=>row.id===id);
const project=id=>state.projects.find(row=>row.id===id);
const account=id=>state.paymentAccounts.find(row=>row.id===id);
const labourer=id=>state.labourers.find(row=>row.id===id);
const material=id=>state.materials.find(row=>row.id===id);
const expenseCategory=id=>state.expenseCategories.find(row=>row.id===id);
const projectLabel=row=>`${row.name} - ${party(row.party_id)?.name||'Unknown party'}`;
const quotePrice=row=>row.pricing_mode==='both'?`${money(row.price_with_material)} / ${money(row.price_without_material)}`:money(row.pricing_mode==='without_material'?row.price_without_material:row.price_with_material);
const projectMetrics=row=>{const entries=state.entries.filter(item=>item.project_id===row.id),sum=type=>entries.filter(item=>item.entry_type===type).reduce((total,item)=>total+Number(item.amount||0),0),increase=sum('scope_increase'),decrease=sum('scope_decrease'),original=Number(row.original_contract_amount||0);return{entries,increase,decrease,original,revised:original+increase-decrease};};
const materialMetrics=row=>{const movements=state.materialMovements.filter(item=>item.material_id===row.id),purchased=movements.filter(item=>['purchase','adjustment_in','walk_in_return'].includes(item.movement_type)).reduce((sum,item)=>sum+Number(item.quantity||0),0),used=movements.filter(item=>['project_issue','walk_in_issue','adjustment_out'].includes(item.movement_type)).reduce((sum,item)=>sum+Number(item.quantity||0),0),latest=[...movements].filter(item=>item.movement_type==='purchase').sort((a,b)=>`${b.movement_date}${b.created_at}`.localeCompare(`${a.movement_date}${a.created_at}`))[0];return{stock:purchased-used,unitCost:Number(latest?.unit_cost??row.default_unit_cost??0)};};
const walkInOrder=id=>state.walkInOrders.find(row=>row.id===id);
const orderLabel=row=>`${row.order_number} - ${row.customer_name}`;
const orderInvoice=row=>state.invoices.find(invoice=>invoice.walk_in_order_id===row.id);
const orderLines=id=>state.orderInvoiceItems.filter(row=>row.walk_in_order_id===id).sort((a,b)=>Number(a.sort_order)-Number(b.sort_order));
const orderDue=row=>Number(row.amount||0)-state.walkInEntries.filter(entry=>entry.walk_in_order_id===row.id&&entry.entry_type==='receipt').reduce((sum,entry)=>sum+Number(entry.amount||0),0);

class Store{
  constructor(){this.base=(cfg.supabaseUrl||'').replace(/\/$/,'');this.key=cfg.supabasePublishableKey||'';}
  headers(extra={}){return{apikey:this.key,Authorization:`Bearer ${state.token}`,'Content-Type':'application/json',...extra};}
  async request(path,options={}){const response=await fetch(`${this.base}${path}`,{...options,headers:this.headers(options.headers)});if(response.status===401){logout(false);throw new Error('Your session expired. Please sign in again.');}if(!response.ok){let message='The action could not be completed.';try{const data=await response.json();message=data.message||data.details||data.hint||message;}catch{}throw new Error(message);}return response.status===204?null:response.json();}
  async signIn(email,password){const response=await fetch(`${this.base}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:this.key,'Content-Type':'application/json'},body:JSON.stringify({email,password})}),data=await response.json();if(!response.ok)throw new Error(data.error_description||data.msg||'Email or password is incorrect.');state.token=data.access_token;state.userId=data.user.id;localStorage.setItem('mi_mobile_session',JSON.stringify({token:state.token,userId:state.userId}));}
  async load(){
    if(!cloud){const saved=JSON.parse(localStorage.getItem('mi_mobile_data')||'{}');state.businessId='demo';state.role='owner';state.business=saved.business||{name:'Mughal Interior'};['parties','projects','entries','invoices','paymentAccounts','payments','labourers','labourAssignments','materials','materialMovements','expenseCategories','walkInOrders','walkInEntries','orderItems','orderInvoiceItems'].forEach(key=>state[key]=saved[key]||[]);return;}
    const memberships=await this.request(`/rest/v1/business_members?select=business_id,role&user_id=eq.${state.userId}&order=created_at.desc&limit=1`);if(!memberships.length)throw new Error('This account has not been added to a business.');state.businessId=memberships[0].business_id;state.role=memberships[0].role;
    [state.parties,state.projects,state.entries,state.invoices,state.paymentAccounts,state.payments,state.labourers,state.labourAssignments,state.materials,state.materialMovements,state.expenseCategories,state.walkInOrders,state.walkInEntries,state.orderItems,state.orderInvoiceItems]=await Promise.all([
      this.request(`/rest/v1/parties?select=*&business_id=eq.${state.businessId}&order=name.asc`),this.request(`/rest/v1/projects?select=*&business_id=eq.${state.businessId}&order=created_at.desc`),this.request(`/rest/v1/project_entries?select=*&business_id=eq.${state.businessId}&order=entry_date.desc,created_at.desc`),this.request(`/rest/v1/invoices?select=*&business_id=eq.${state.businessId}&order=created_at.desc`),this.request(`/rest/v1/payment_accounts?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/payments?select=*&business_id=eq.${state.businessId}&order=payment_date.desc,created_at.desc`),this.request(`/rest/v1/labourers?select=*&business_id=eq.${state.businessId}&order=name.asc`),this.request(`/rest/v1/labour_assignments?select=*&business_id=eq.${state.businessId}&order=assignment_date.desc,created_at.desc`),this.request(`/rest/v1/materials?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/material_movements?select=*&business_id=eq.${state.businessId}&order=movement_date.desc,created_at.desc`),this.request(`/rest/v1/expense_categories?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/walk_in_orders?select=*&business_id=eq.${state.businessId}&order=order_date.desc,created_at.desc`),this.request(`/rest/v1/walk_in_order_entries?select=*&business_id=eq.${state.businessId}&order=entry_date.desc,created_at.desc`),this.request(`/rest/v1/order_items?select=*&business_id=eq.${state.businessId}&active=eq.true&order=name.asc`),this.request(`/rest/v1/order_invoice_items?select=*&business_id=eq.${state.businessId}&order=sort_order.asc`)
    ]);const businesses=await this.request(`/rest/v1/businesses?select=*&id=eq.${state.businessId}&limit=1`);state.business=businesses[0]||{name:'Mughal Interior'};
  }
  persist(){if(!cloud)localStorage.setItem('mi_mobile_data',JSON.stringify({business:state.business,parties:state.parties,projects:state.projects,entries:state.entries,invoices:state.invoices,paymentAccounts:state.paymentAccounts,payments:state.payments,labourers:state.labourers,labourAssignments:state.labourAssignments,materials:state.materials,materialMovements:state.materialMovements,expenseCategories:state.expenseCategories,walkInOrders:state.walkInOrders,walkInEntries:state.walkInEntries,orderItems:state.orderItems,orderInvoiceItems:state.orderInvoiceItems}));}
  async save(table,row,updating=false){if(!cloud)return{...row,business_id:state.businessId,updated_at:new Date().toISOString()};const payload={...row,business_id:state.businessId},path=updating?`/rest/v1/${table}?id=eq.${row.id}`:`/rest/v1/${table}`,result=await this.request(path,{method:updating?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(payload)});return result[0];}
  async remove(table,id){if(!cloud)return;const removed=await this.request(`/rest/v1/${table}?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=representation'}});if(!removed?.length)throw new Error('Only the business owner can delete this record.');}
  async rpc(name,payload){return this.request(`/rest/v1/rpc/${name}`,{method:'POST',body:JSON.stringify(payload)});}
}
const store=new Store();

function toast(message){const node=$('#toast');node.textContent=message;node.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.add('hidden'),3200);}
async function working(label,button,action){const overlay=$('#processing'),old=button?.textContent;if(button){button.disabled=true;button.classList.add('processing');button.textContent='Please wait…';}$('#processingText').textContent=label;overlay.classList.remove('hidden');try{return await action();}catch(error){toast(error.message);throw error;}finally{overlay.classList.add('hidden');if(button){button.disabled=false;button.classList.remove('processing');button.textContent=old;}}}
function openSheet(id){$('#backdrop').classList.remove('hidden');$(id).classList.remove('hidden');document.body.style.overflow='hidden';}
function closeSheets(){$('#backdrop').classList.add('hidden');$$('.sheet').forEach(node=>node.classList.add('hidden'));document.body.style.overflow='';}
function route(name){const map={projectsHub:'Projects',parties:'Parties',projectMaster:'Projects',quotes:'Quotes',invoices:'Invoices',receipts:'Receive payments',labour:'Assign labour',materials:'Assign material',expenses:'Charge expenses',orders:'Orders',orderInvoices:'Order invoices',orderReceipts:'Order receipts',orderExpenses:'Order expenses',orderMaterials:'Order materials',orderLabour:'Order labour',orderItems:'Order items',suppliers:'Suppliers',banking:'Banking',reports:'Reports'};$$('.view').forEach(node=>node.classList.toggle('active',node.id===`${name}View`));$('#screenTitle').textContent=map[name]||'Projects';window.scrollTo({top:0,behavior:'instant'});render();}
function tab(name){$$('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===name));route(name);}
function empty(title,text){return`<div class="empty"><b>${esc(title)}</b><span>${esc(text)}</span></div>`;}
function upsert(list,row){const index=list.findIndex(item=>item.id===row.id);index>=0?list.splice(index,1,row):list.unshift(row);store.persist();}
function options(rows,label,placeholder='Select an option'){return`<option value="">${esc(placeholder)}</option>${rows.map(row=>`<option value="${row.id}">${esc(label(row))}</option>`).join('')}`;}

function renderParties(){const q=$('#partySearch').value.toLowerCase(),rows=state.parties.filter(r=>[r.name,r.phone,r.address].join(' ').toLowerCase().includes(q));$('#partyList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${shortCode('PTY',r.id)}</span><h3>${esc(r.name)}</h3><div class="record-meta">${r.phone?`<span>${esc(r.phone)}</span>`:''}${r.address?`<span>${esc(r.address)}</span>`:''}</div></div><button class="view-button" data-view-party="${r.id}">View</button></div></article>`).join(''):empty('No parties found','Add your first customer.');}
function renderProjects(){const q=$('#projectSearch').value.toLowerCase(),rows=state.projects.filter(r=>[r.project_number,r.name,r.location,party(r.party_id)?.name].join(' ').toLowerCase().includes(q));$('#projectList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.project_number||shortCode('PRJ',r.id))}</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(party(r.party_id)?.name||'Unknown party')}</span>${r.location?`<span>${esc(r.location)}</span>`:''}<span>${r.quote_created?'Quote added':'No quote'}</span></div></div><button class="view-button" data-view-project="${r.id}">View</button></div></article>`).join(''):empty('No projects found','Add a project record to begin.');}
function renderQuotes(){const q=$('#quoteSearch').value.toLowerCase(),rows=state.projects.filter(r=>r.quote_created&&[r.project_number,r.name,party(r.party_id)?.name].join(' ').toLowerCase().includes(q));$('#quoteList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.project_number)}</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(party(r.party_id)?.name||'Unknown party')}</span><span>${date(r.quote_date)}</span><span>${quotePrice(r)}</span></div></div><div class="record-side"><span class="status ${r.status==='Approved'?'approved':''}">${esc(r.status)}</span><button class="view-button" data-view-quote="${r.id}">View</button></div></div></article>`).join(''):empty('No quotes found','Add a quote for a saved project.');}
function renderInvoices(){const q=$('#invoiceSearch').value.toLowerCase(),rows=state.invoices.filter(r=>r.project_id).filter(r=>{const job=project(r.project_id);return[r.invoice_number,job?.name,party(job?.party_id)?.name].join(' ').toLowerCase().includes(q)});$('#invoiceList').innerHTML=rows.length?rows.map(r=>{const job=project(r.project_id),total=job?projectMetrics(job).revised:r.amount;return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.invoice_number)}</span><h3>${esc(job?.name||'Project invoice')}</h3><div class="record-meta"><span>${esc(party(job?.party_id)?.name||'Unknown party')}</span><span>${date(r.invoice_date)}</span></div></div><div class="record-side"><strong>${money(total)}</strong><button class="view-button" data-view-invoice="${r.id}">View</button></div></div><div class="card-actions"><button class="button secondary block" data-download-invoice="${r.id}">Download PDF</button></div></article>`}).join(''):empty('No invoices found','Approved quotes appear here automatically.');}
function renderReceipts(){const q=$('#receiptSearch').value.toLowerCase(),rows=state.payments.filter(r=>r.payment_type==='customer_receipt'&&r.project_id).filter(r=>{const job=project(r.project_id);return[r.payment_number,r.description,job?.name,party(r.party_id)?.name].join(' ').toLowerCase().includes(q)});$('#receiptList').innerHTML=rows.length?rows.map(r=>{const job=project(r.project_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.payment_number||shortCode('RCP',r.id))}</span><h3>${esc(job?.name||'Project receipt')}</h3><div class="record-meta"><span>${esc(party(r.party_id)?.name||'Unknown party')}</span><span>${date(r.payment_date)}</span><span>${esc(account(r.to_account_id)?.name||'Account')}</span></div></div><div class="record-side"><strong class="record-total">${money(r.amount)}</strong><button class="view-button" data-view-receipt="${r.id}">View</button></div></div></article>`}).join(''):empty('No payments received','Record the first project receipt.');}
function renderLabour(){$('#labourPersonList').innerHTML=state.labourers.length?state.labourers.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.joining_date||r.record_date||r.created_at)}</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(r.speciality||'Speciality not set')}</span><span>${money(r.daily_wage_rate)} daily</span></div></div><button class="view-button" data-view-labour-person="${r.id}">View</button></div></article>`).join(''):empty('No labour persons','Add a labour person before assigning wages.');$('#labourAssignmentList').innerHTML=state.labourAssignments.length?state.labourAssignments.map(r=>{const job=project(r.project_id),worker=labourer(r.labourer_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.assignment_date)}</span><h3>${esc(worker?.name||'Labour')}</h3><div class="record-meta"><span>${esc(job?projectLabel(job):'Project')}</span><span>${Number(r.days)===.5?'Half day':'Full day'}</span></div></div><div class="record-side"><strong>${money(r.amount??Number(r.days)*Number(r.daily_rate))}</strong><button class="view-button" data-view-labour-assignment="${r.id}">View</button></div></div></article>`}).join(''):empty('No labour assigned','Assign a labour person to an approved project.');}
function renderMaterials(){const q=$('#materialAssignmentSearch').value.toLowerCase(),rows=state.materialMovements.filter(r=>r.movement_type==='project_issue').filter(r=>{const job=project(r.project_id);return[material(r.material_id)?.name,job?.name,party(job?.party_id)?.name,r.notes].join(' ').toLowerCase().includes(q)});$('#materialAssignmentList').innerHTML=rows.length?rows.map(r=>{const item=material(r.material_id),job=project(r.project_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.movement_date)}</span><h3>${esc(item?.name||'Material')}</h3><div class="record-meta"><span>${esc(job?projectLabel(job):'Project')}</span><span>${qty(r.quantity)} ${esc(item?.unit||'units')}</span></div></div><div class="record-side"><strong>${money(Number(r.quantity)*Number(r.unit_cost))}</strong><button class="view-button" data-view-material-assignment="${r.id}">View</button></div></div></article>`}).join(''):empty('No material assigned','Assign purchased material to an approved project.');}
function renderExpenses(){$('#expenseCategoryList').innerHTML=state.expenseCategories.length?state.expenseCategories.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">EXPENSE MASTER</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(r.description||'No details')}</span></div></div><button class="view-button" data-view-expense-category="${r.id}">View</button></div></article>`).join(''):empty('No expense types','Add the first project expense type.');const charges=state.entries.filter(r=>r.entry_type==='expense');$('#expenseChargeList').innerHTML=charges.length?charges.map(r=>{const job=project(r.project_id),cat=expenseCategory(r.expense_category_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.entry_date)}</span><h3>${esc(cat?.name||r.description)}</h3><div class="record-meta"><span>${esc(job?projectLabel(job):'Project')}</span>${r.notes?`<span>${esc(r.notes)}</span>`:''}</div></div><div class="record-side"><strong>${money(r.amount)}</strong><button class="view-button" data-view-expense-charge="${r.id}">View</button></div></div></article>`}).join(''):empty('No expenses charged','Charge an expense to an approved project.');}
function renderOrderInvoices(){const q=$('#orderInvoiceSearch').value.toLowerCase(),rows=state.walkInOrders.filter(r=>orderInvoice(r)).filter(r=>[r.order_number,r.customer_name,r.customer_phone,orderInvoice(r)?.invoice_number].join(' ').toLowerCase().includes(q));$('#orderInvoiceList').innerHTML=rows.length?rows.map(r=>{const invoice=orderInvoice(r);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(invoice?.invoice_number||r.order_number)}</span><h3>${esc(r.customer_name)}</h3><div class="record-meta"><span>${date(invoice?.invoice_date||r.order_date)}</span>${r.customer_phone?`<span>${esc(r.customer_phone)}</span>`:''}<span>${orderLines(r.id).length} items</span></div></div><div class="record-side"><strong>${money(r.amount)}</strong><button class="view-button" data-view-order-invoice="${r.id}">View</button></div></div></article>`}).join(''):empty('No order invoices','Create the first direct customer invoice.');}
function renderOrderReceipts(){const q=$('#orderReceiptSearch').value.toLowerCase(),rows=state.payments.filter(r=>r.payment_type==='customer_receipt'&&r.walk_in_order_id).filter(r=>{const order=walkInOrder(r.walk_in_order_id);return[r.payment_number,r.description,order?.order_number,order?.customer_name].join(' ').toLowerCase().includes(q)});$('#orderReceiptList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${esc(r.payment_number)}</span><h3>${esc(order?.customer_name||'Order receipt')}</h3><div class="record-meta"><span>${esc(order?.order_number||'Order')}</span><span>${date(r.payment_date)}</span><span>${esc(account(r.to_account_id)?.name||'Account')}</span></div></div><div class="record-side"><strong class="record-total">${money(r.amount)}</strong><button class="view-button" data-view-order-receipt="${r.id}">View</button></div></div></article>`}).join(''):empty('No order receipts','Receive the first payment against an order.');}
function renderOrderExpenses(){$('#orderExpenseCategoryList').innerHTML=$('#expenseCategoryList').innerHTML;const rows=state.walkInEntries.filter(r=>r.entry_type==='expense');$('#orderExpenseChargeList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id),cat=expenseCategory(r.expense_category_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.entry_date)}</span><h3>${esc(cat?.name||r.description)}</h3><div class="record-meta"><span>${esc(order?orderLabel(order):'Order')}</span>${r.notes?`<span>${esc(r.notes)}</span>`:''}</div></div><div class="record-side"><strong>${money(r.amount)}</strong><button class="view-button" data-view-order-expense="${r.id}">View</button></div></div></article>`}).join(''):empty('No order expenses','Assign an expense to an order.');}
function renderOrderMaterials(){const q=$('#orderMaterialSearch').value.toLowerCase(),rows=state.materialMovements.filter(r=>['walk_in_issue','walk_in_return'].includes(r.movement_type)).filter(r=>{const order=walkInOrder(r.walk_in_order_id);return[material(r.material_id)?.name,order?.customer_name,order?.order_number,r.notes].join(' ').toLowerCase().includes(q)});$('#orderMaterialList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id),item=material(r.material_id),returned=r.movement_type==='walk_in_return';return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.movement_date)}</span><h3>${esc(item?.name||'Material')} <span class="inline-badge">${returned?'Returned':'Assigned'}</span></h3><div class="record-meta"><span>${esc(order?orderLabel(order):'Order')}</span><span>${qty(r.quantity)} ${esc(item?.unit||'units')}</span></div></div><div class="record-side"><strong class="${returned?'positive':''}">${returned?'+':'−'} ${money(Number(r.quantity)*Number(r.unit_cost))}</strong><button class="view-button" data-view-order-material="${r.id}">View</button></div></div></article>`}).join(''):empty('No order material activity','Assign purchased material or record a return.');}
function renderOrderLabour(){$('#orderLabourPersonList').innerHTML=$('#labourPersonList').innerHTML;const rows=state.labourAssignments.filter(r=>r.walk_in_order_id);$('#orderLabourAssignmentList').innerHTML=rows.length?rows.map(r=>{const order=walkInOrder(r.walk_in_order_id),worker=labourer(r.labourer_id);return`<article class="record-card"><div class="record-top"><div><span class="record-id">${date(r.assignment_date)}</span><h3>${esc(worker?.name||'Labour')}</h3><div class="record-meta"><span>${esc(order?orderLabel(order):'Order')}</span><span>${Number(r.days)===.5?'Half day':'Full day'}</span></div></div><div class="record-side"><strong>${money(r.amount??Number(r.days)*Number(r.daily_rate))}</strong><button class="view-button" data-view-order-labour="${r.id}">View</button></div></div></article>`}).join(''):empty('No order labour assigned','Assign a labour person to an order.');}
function renderOrderItems(){const q=$('#orderItemSearch').value.toLowerCase(),rows=state.orderItems.filter(r=>[r.name,r.details].join(' ').toLowerCase().includes(q));$('#orderItemList').innerHTML=rows.length?rows.map(r=>`<article class="record-card"><div class="record-top"><div><span class="record-id">INVOICE ITEM</span><h3>${esc(r.name)}</h3><div class="record-meta"><span>${esc(r.details||'No details')}</span></div></div><button class="view-button" data-view-order-item="${r.id}">View</button></div></article>`).join(''):empty('No invoice items','Add items such as tables, doors or cupboards.');}
function renderOrders(){renderOrderInvoices();renderOrderReceipts();renderOrderExpenses();renderOrderMaterials();renderOrderLabour();renderOrderItems();$('#orderHubValue').textContent=money(state.walkInOrders.reduce((sum,r)=>sum+Number(r.amount||0),0));$('#orderHubInvoiceCount').textContent=state.walkInOrders.filter(r=>orderInvoice(r)).length;$('#orderHubReceiptCount').textContent=state.payments.filter(r=>r.payment_type==='customer_receipt'&&r.walk_in_order_id).length;$('#orderHubItemCount').textContent=state.orderItems.length;$('#orderCustomerPhoneOptions').innerHTML=[...new Map(state.walkInOrders.filter(r=>r.customer_phone).map(r=>[r.customer_phone,r])).values()].map(r=>`<option value="${esc(r.customer_phone)}">${esc(r.customer_name)}</option>`).join('');}
function render(){renderParties();renderProjects();renderQuotes();renderInvoices();renderReceipts();renderLabour();renderMaterials();renderExpenses();renderOrders();$('#hubApprovedValue').textContent=money(state.projects.filter(r=>r.status==='Approved').reduce((sum,r)=>sum+projectMetrics(r).revised,0));$('#hubPartyCount').textContent=state.parties.length;$('#hubQuoteCount').textContent=state.projects.filter(r=>r.quote_created).length;$('#hubInvoiceCount').textContent=state.invoices.filter(r=>r.project_id).length;$('#partyOptions').innerHTML=state.parties.map(r=>`<option value="${esc(r.name)}"></option>`).join('');$('#quoteProjectOptions').innerHTML=state.projects.map(r=>`<option value="${esc(projectLabel(r))}"></option>`).join('');}

const approvedProjects=()=>state.projects.filter(r=>r.status==='Approved');
function openParty(id=''){const r=party(id),next=id||uid();$('#partyForm').reset();$('#partyId').value=next;$('#partyCode').value=shortCode('PTY',next);$('#partyName').value=r?.name||'';$('#partyPhone').value=r?.phone||'';$('#partyAddress').value=r?.address||'';$('#partySheetTitle').textContent=r?'Edit party':'Add party';openSheet('#partySheet');}
function openProject(id=''){if(!state.parties.length){toast('Add a party before creating a project.');route('parties');return;}const r=project(id),next=id||uid();$('#projectForm').reset();$('#projectId').value=next;$('#projectCode').value=r?.project_number||shortCode('PRJ',next);$('#projectName').value=r?.name||'';$('#projectPartySearch').value=party(r?.party_id)?.name||'';$('#projectLocation').value=r?.location||'';$('#projectSheetTitle').textContent=r?'Edit project':'Add project';openSheet('#projectSheet');}
const resolveParty=name=>state.parties.find(r=>r.name.toLowerCase()===name.trim().toLowerCase());
const resolveProject=label=>state.projects.find(r=>projectLabel(r).toLowerCase()===label.trim().toLowerCase());
function setQuoteDays(){$('#quoteDays').value=daysBetween($('#quoteStart').value,$('#quoteEnd').value);}
function openQuote(id=''){if(!state.projects.length){toast('Add a project before creating a quote.');route('projectMaster');return;}const r=project(id);$('#quoteForm').reset();$('#quoteProjectId').value=id;$('#quoteProjectSearch').value=r?projectLabel(r):'';$('#quoteProjectSearch').readOnly=Boolean(r);$('#quoteDate').value=r?.quote_date||today();$('#quoteStart').value=r?.start_date||'';$('#quoteEnd').value=r?.expected_end_date||'';$('#quoteDays').value=r?.days_to_complete??'';$('#quoteDetails').value=r?.description||'';$('#quoteWithMaterial').value=r?.price_with_material??'';$('#quoteWithoutMaterial').value=r?.price_without_material??'';$('#quoteShowBoth').checked=r?.pricing_mode==='both';$('#quotePaymentTerms').value=r?.payment_terms||state.business?.default_payment_terms||'';$('#quoteNotes').value=r?.notes||'';$('#quoteSheetTitle').textContent=r?.quote_created?'Edit quote':'Add quote';openSheet('#quoteSheet');}
function openReceipt(id=''){if(!approvedProjects().length){toast('Approve a project quote before receiving payment.');route('quotes');return;}if(!state.paymentAccounts.length){toast('Add a bank or cash account in Banking first.');tab('banking');return;}const r=state.payments.find(x=>x.id===id);$('#receiptForm').reset();$('#receiptId').value=r?.id||'';$('#receiptProject').innerHTML=options(approvedProjects(),projectLabel,'Select project - party');$('#receiptProject').value=r?.project_id||'';$('#receiptProject').disabled=Boolean(r);$('#receiptDate').value=r?.payment_date||today();$('#receiptAccount').innerHTML=options(state.paymentAccounts,x=>`${x.name}${x.bank_name?` - ${x.bank_name}`:''}`,'Select bank / cash account');$('#receiptAccount').value=r?.to_account_id||'';$('#receiptAmount').value=r?.amount??'';$('#receiptDetails').value=r?.description||'';$('#receiptSheetTitle').textContent=r?'Edit received payment':'Payment received';openSheet('#receiptSheet');}
function openLabourPerson(id=''){const r=labourer(id);$('#labourPersonForm').reset();$('#labourPersonId').value=r?.id||'';$('#labourRecordDate').value=r?.record_date||String(r?.created_at||today()).slice(0,10);$('#labourName').value=r?.name||'';$('#labourJoiningDate').value=r?.joining_date||'';$('#labourDailyWage').value=r?.daily_wage_rate??'';$('#labourSpeciality').value=r?.speciality||'';$('#labourPersonSheetTitle').textContent=r?'Edit labour person':'Add labour person';openSheet('#labourPersonSheet');}
function updateLabourCost(){const worker=labourer($('#labourAssignmentPerson').value),rate=Number(worker?.daily_wage_rate||0),days=Number($('#labourDayType').value||1);$('#labourAssignmentRate').value=rate;$('#labourActualCost').value=(rate*days).toFixed(2);}
function openLabourAssignment(){if(!approvedProjects().length){toast('Approve a project quote before assigning labour.');return;}if(!state.labourers.length){toast('Add a labour person first.');showLabourTab('persons');return;}$('#labourAssignmentForm').reset();$('#labourAssignmentDate').value=today();$('#labourAssignmentProject').innerHTML=options(approvedProjects(),projectLabel,'Select project - party');$('#labourAssignmentPerson').innerHTML=options(state.labourers.filter(r=>r.active!==false),r=>`${r.name} - ${money(r.daily_wage_rate)}`,'Select labour person');$('#labourDayType').value='1';updateLabourCost();openSheet('#labourAssignmentSheet');}
function updateMaterialCost(){const item=material($('#materialAssignmentMaterial').value),metric=item?materialMetrics(item):{stock:0,unitCost:0},amount=Number($('#materialAssignmentQuantity').value||0);$('#materialAssignmentRate').value=metric.unitCost.toFixed(2);$('#materialAssignmentTotal').value=(metric.unitCost*amount).toFixed(2);$('#materialStockHelp').textContent=item?`Available: ${qty(metric.stock)} ${item.unit}. Cost is from the latest purchase.`:'';}
function openMaterialAssignment(){if(!approvedProjects().length){toast('Approve a project quote before assigning material.');return;}if(!state.materials.length){toast('Add materials and purchases in Suppliers first.');tab('suppliers');return;}$('#materialAssignmentForm').reset();$('#materialAssignmentDate').value=today();$('#materialAssignmentProject').innerHTML=options(approvedProjects(),projectLabel,'Select project - party');$('#materialAssignmentMaterial').innerHTML=options(state.materials,r=>`${r.name} - ${qty(materialMetrics(r).stock)} ${r.unit} available`,'Select purchased material');updateMaterialCost();openSheet('#materialAssignmentSheet');}
function openExpenseCategory(id=''){const r=expenseCategory(id);$('#expenseCategoryForm').reset();$('#expenseCategoryId').value=r?.id||'';$('#expenseCategoryName').value=r?.name||'';$('#expenseCategoryDetails').value=r?.description||'';$('#expenseCategorySheetTitle').textContent=r?'Edit expense':'Add expense';openSheet('#expenseCategorySheet');}
function openExpenseCharge(){if(!approvedProjects().length){toast('Approve a project quote before charging expenses.');return;}if(!state.expenseCategories.length){toast('Add an expense type first.');showExpenseTab('list');return;}$('#expenseChargeForm').reset();$('#expenseChargeDate').value=today();$('#expenseChargeProject').innerHTML=options(approvedProjects(),projectLabel,'Select project - party');$('#expenseChargeCategory').innerHTML=options(state.expenseCategories,r=>r.name,'Select expense');openSheet('#expenseChargeSheet');}
function openScope(){const rows=approvedProjects().filter(r=>state.invoices.some(i=>i.project_id===r.id));if(!rows.length){toast('No approved project invoice is available.');return;}$('#scopeForm').reset();$('#scopeProject').innerHTML=rows.map(r=>`<option value="${r.id}">${esc(projectLabel(r))}</option>`).join('');$('#scopeDate').value=today();openSheet('#scopeSheet');}
function invoiceItemOptions(selected=''){return options(state.orderItems,r=>r.name,'Select item').replace(`value="${selected}"`,`value="${selected}" selected`);}
function addOrderInvoiceLine(data={}){const line=document.createElement('div');line.className='invoice-line';line.innerHTML=`<div class="invoice-line-head"><b>Invoice item</b><button class="remove-line" type="button" data-remove-order-line>×</button></div><div class="invoice-line-grid"><label class="wide">Item *<select data-order-line-item required>${invoiceItemOptions(data.order_item_id||'')}</select></label><label class="wide">Details<textarea data-order-line-details rows="2">${esc(data.details||'')}</textarea></label><label>Qty *<input data-order-line-qty type="number" min="0.001" step="0.001" value="${Number(data.quantity||1)}" required></label><label>Rate *<input data-order-line-rate type="number" min="0" step="0.01" value="${Number(data.rate||0)}" required></label><label class="wide">Amount<input data-order-line-amount value="${money(Number(data.quantity||1)*Number(data.rate||0))}" readonly></label></div>`;$('#orderInvoiceLines').append(line);recalcOrderInvoice();}
function readOrderInvoiceLines(){return $$('.invoice-line',$('#orderInvoiceLines')).map(line=>({order_item_id:$('[data-order-line-item]',line).value,details:$('[data-order-line-details]',line).value.trim()||null,quantity:Number($('[data-order-line-qty]',line).value),rate:Number($('[data-order-line-rate]',line).value)}));}
function recalcOrderInvoice(){const subtotal=readOrderInvoiceLines().reduce((sum,line)=>sum+(line.quantity||0)*(line.rate||0),0),discount=Number($('#orderInvoiceDiscount').value||0),total=Math.max(0,subtotal-discount);$('#orderInvoiceSubtotal').textContent=money(subtotal);$('#orderInvoiceGrandTotal').textContent=money(total);$$('.invoice-line',$('#orderInvoiceLines')).forEach(line=>{$('[data-order-line-amount]',line).value=money(Number($('[data-order-line-qty]',line).value||0)*Number($('[data-order-line-rate]',line).value||0))});}
function openOrderInvoice(id=''){if(!state.orderItems.length){toast('Add an invoice item first.');route('orderItems');return;}const order=walkInOrder(id);$('#orderInvoiceForm').reset();$('#orderInvoiceOrderId').value=order?.id||'';$('#orderInvoiceDate').value=orderInvoice(order||{})?.invoice_date||order?.order_date||today();$('#orderInvoiceMobile').value=order?.customer_phone||'';$('#orderInvoiceCustomer').value=order?.customer_name||'';$('#orderInvoiceDetails').value=order?.description||'';$('#orderInvoiceDiscount').value=Number(order?.discount||0);$('#orderInvoiceLines').innerHTML='';const lines=order?orderLines(order.id):[];(lines.length?lines:[{}]).forEach(addOrderInvoiceLine);$('#orderInvoiceSheetTitle').textContent=order?'Edit invoice':'Add invoice';recalcOrderInvoice();openSheet('#orderInvoiceSheet');}
function autofillOrderCustomer(){const phone=$('#orderInvoiceMobile').value.trim(),old=[...state.walkInOrders].reverse().find(r=>r.customer_phone===phone);if(old)$('#orderInvoiceCustomer').value=old.customer_name;}
function openOrderReceipt(id=''){if(!state.walkInOrders.length){toast('Add an order invoice first.');route('orderInvoices');return;}if(!state.paymentAccounts.length){toast('Add a bank or cash account in Banking first.');tab('banking');return;}const receipt=state.payments.find(r=>r.id===id);$('#orderReceiptForm').reset();$('#orderReceiptId').value=receipt?.id||'';$('#orderReceiptOrder').innerHTML=options(state.walkInOrders.filter(r=>r.status!=='Cancelled'),orderLabel,'Select order - customer');$('#orderReceiptOrder').value=receipt?.walk_in_order_id||'';$('#orderReceiptOrder').disabled=Boolean(receipt);$('#orderReceiptDate').value=receipt?.payment_date||today();$('#orderReceiptAccount').innerHTML=options(state.paymentAccounts,r=>`${r.name}${r.bank_name?` - ${r.bank_name}`:''}`,'Select bank / cash account');$('#orderReceiptAccount').value=receipt?.to_account_id||'';$('#orderReceiptAmount').value=receipt?.amount??'';$('#orderReceiptDetails').value=receipt?.description||'';$('#orderReceiptSheetTitle').textContent=receipt?'Edit received payment':'Receive payment';openSheet('#orderReceiptSheet');}
function openOrderExpense(){if(!state.walkInOrders.length){toast('Add an order invoice first.');return;}if(!state.expenseCategories.length){toast('Add an expense type first.');showOrderExpenseTab('list');return;}$('#orderExpenseChargeForm').reset();$('#orderExpenseDate').value=today();$('#orderExpenseOrder').innerHTML=options(state.walkInOrders.filter(r=>r.status!=='Cancelled'),orderLabel,'Select order - customer');$('#orderExpenseCategory').innerHTML=options(state.expenseCategories,r=>r.name,'Select expense');openSheet('#orderExpenseChargeSheet');}
function orderReturnable(orderId,materialId){return state.materialMovements.filter(r=>r.walk_in_order_id===orderId&&r.material_id===materialId).reduce((sum,r)=>sum+(r.movement_type==='walk_in_issue'?Number(r.quantity||0):r.movement_type==='walk_in_return'?-Number(r.quantity||0):0),0);}
function updateOrderMaterialCost(){const item=material($('#orderMaterialItem').value),mode=$('#orderMaterialMode').value,orderId=$('#orderMaterialOrder').value,metric=item?materialMetrics(item):{stock:0,unitCost:0},quantity=Number($('#orderMaterialQuantity').value||0),available=mode==='return'&&item?orderReturnable(orderId,item.id):metric.stock;$('#orderMaterialRate').value=metric.unitCost.toFixed(2);$('#orderMaterialTotal').value=(metric.unitCost*quantity).toFixed(2);$('#orderMaterialHelp').textContent=item?`${mode==='return'?'Returnable from this order':'Available stock'}: ${qty(available)} ${item.unit}`:'';}
function openOrderMaterial(mode='assign'){if(!state.walkInOrders.length){toast('Add an order invoice first.');return;}if(!state.materials.length){toast('Add materials and purchases in Suppliers first.');tab('suppliers');return;}$('#orderMaterialForm').reset();$('#orderMaterialMode').value=mode;$('#orderMaterialDate').value=today();$('#orderMaterialOrder').innerHTML=options(state.walkInOrders.filter(r=>['Pending','In Progress','Ready'].includes(r.status)),orderLabel,'Select order - customer');$('#orderMaterialItem').innerHTML=options(state.materials,r=>r.name,'Select material');$('#orderMaterialSheetTitle').textContent=mode==='return'?'Return material':'Assign material';updateOrderMaterialCost();openSheet('#orderMaterialSheet');}
function updateOrderLabourCost(){const worker=labourer($('#orderLabourPerson').value),rate=Number(worker?.daily_wage_rate||0),days=Number($('#orderLabourDay').value||1);$('#orderLabourRate').value=rate;$('#orderLabourTotal').value=(rate*days).toFixed(2);}
function openOrderLabour(){if(!state.walkInOrders.length){toast('Add an order invoice first.');return;}if(!state.labourers.length){toast('Add a labour person first.');showOrderLabourTab('persons');return;}$('#orderLabourForm').reset();$('#orderLabourDate').value=today();$('#orderLabourOrder').innerHTML=options(state.walkInOrders.filter(r=>r.status!=='Cancelled'),orderLabel,'Select order - customer');$('#orderLabourPerson').innerHTML=options(state.labourers.filter(r=>r.active!==false),r=>`${r.name} - ${money(r.daily_wage_rate)}`,'Select labour person');$('#orderLabourDay').value='1';updateOrderLabourCost();openSheet('#orderLabourSheet');}
function openOrderItem(id=''){const item=state.orderItems.find(r=>r.id===id);$('#orderItemForm').reset();$('#orderItemId').value=item?.id||'';$('#orderItemName').value=item?.name||'';$('#orderItemDetails').value=item?.details||'';$('#orderItemSheetTitle').textContent=item?'Edit item':'Add item';openSheet('#orderItemSheet');}
function showOrderExpenseTab(name){$$('[data-order-expense-tab]').forEach(b=>b.classList.toggle('active',b.dataset.orderExpenseTab===name));$('#orderExpenseListPanel').classList.toggle('active',name==='list');$('#orderExpenseChargesPanel').classList.toggle('active',name==='charges');}
function showOrderLabourTab(name){$$('[data-order-labour-tab]').forEach(b=>b.classList.toggle('active',b.dataset.orderLabourTab===name));$('#orderLabourPersonsPanel').classList.toggle('active',name==='persons');$('#orderLabourAssignmentsPanel').classList.toggle('active',name==='assignments');}

function detailRows(rows){return`<div class="detail-grid">${rows.map(([label,value])=>`<div class="detail-row"><span>${esc(label)}</span><b>${esc(value||'Not entered')}</b></div>`).join('')}</div>`;}
function setupDetail(type,row,{title,kicker,html,actions='',editable=true,deletable=true,documentName=''}){state.detail={type,id:row.id,documentName:documentName||`${type}-${row.id}`};$('#detailKicker').textContent=kicker;$('#detailTitle').textContent=title;$('#detailBody').innerHTML=html;$('#detailActions').innerHTML=actions;$('#detailEdit').classList.toggle('hidden',!editable);$('#dangerZone').classList.toggle('hidden',!deletable||state.role!=='owner');$('#detailDelete').textContent=`Delete ${type.replace(/([A-Z])/g,' $1').toLowerCase()}`;closeSheets();openSheet('#detailSheet');}
const detailCard=(eyebrow,title,amount,rows,pdf=false)=>`<article class="detail-card ${pdf?'pdf-document':''}"><div class="detail-hero"><p>${esc(eyebrow)}</p><h3>${esc(title)}</h3>${amount?`<div class="detail-amount">${esc(amount)}</div>`:''}</div>${detailRows(rows)}</article>`;
function viewParty(id){const r=party(id);if(r)setupDetail('party',r,{title:r.name,kicker:'PARTY DETAILS',html:detailCard(shortCode('PTY',r.id),r.name,'',[['Mobile number',r.phone],['Address',r.address]])});}
function viewProject(id){const r=project(id);if(r)setupDetail('project',r,{title:r.name,kicker:'PROJECT DETAILS',html:detailCard(r.project_number,r.name,'',[['Party',party(r.party_id)?.name],['Location',r.location],['Quote',r.quote_created?'Created':'Not created'],['Status',r.status]])});}
function quoteDocument(r){const prices=r.pricing_mode==='both'?[['Amount with material',money(r.price_with_material)],['Amount without material',money(r.price_without_material)]]:r.pricing_mode==='without_material'?[['Amount without material',money(r.price_without_material)]]:[['Amount with material',money(r.price_with_material)]];return detailCard(`PROJECT QUOTATION · ${r.project_number}`,r.name,quotePrice(r),[['Business',state.business?.name||'Mughal Interior'],['Party',party(r.party_id)?.name],['Location',r.location],['Quote date',date(r.quote_date)],['Project start',date(r.start_date)],['End date',date(r.expected_end_date)],['No. of days',String(r.days_to_complete??'Not set')],['Project details',r.description],...prices,['Payment terms',r.payment_terms],['Other details',r.notes],['Status',r.status]],true);}
function viewQuote(id){const r=project(id);if(!r)return;const approved=r.status==='Approved';setupDetail('quote',r,{title:r.name,kicker:'QUOTE DETAILS',html:quoteDocument(r),actions:`<button class="button secondary block" data-detail-download>Download quote PDF</button>${approved?'':`<button class="button primary block" data-approve-quote="${r.id}">Approve quote</button>`}`,deletable:!approved,documentName:`quote-${r.project_number}`});}
function invoiceDocument(r){const job=project(r.project_id);if(!job)return'';const metric=projectMetrics(job),changes=metric.entries.filter(x=>['scope_increase','scope_decrease'].includes(x.entry_type));return`<article class="detail-card pdf-document"><div class="detail-hero"><p>PROJECT INVOICE · ${esc(r.invoice_number)}</p><h3>${esc(job.name)}</h3><div class="detail-amount">${money(metric.revised)}</div></div>${detailRows([['Business',state.business?.name||'Mughal Interior'],['Party',party(job.party_id)?.name],['Location',job.location],['Invoice date',date(r.invoice_date)],['Original project scope',job.description],['Original approved amount',money(metric.original)]])}${changes.length?`<div class="scope-list"><h4>Scope additions and deletions</h4>${changes.map(x=>`<div class="scope-item"><div><b>${esc(x.description)}</b><small>${date(x.entry_date)} · ${x.entry_type==='scope_increase'?'Scope increase':'Scope decrease'}</small></div><strong class="${x.entry_type==='scope_decrease'?'negative':''}">${x.entry_type==='scope_decrease'?'-':'+'}${money(x.amount)}</strong></div>`).join('')}</div>`:''}${detailRows([['Total increase',money(metric.increase)],['Total decrease',`− ${money(metric.decrease)}`],['Revised invoice amount',money(metric.revised)]])}</article>`;}
function viewInvoice(id){const r=state.invoices.find(x=>x.id===id);if(r)setupDetail('invoice',r,{title:r.invoice_number,kicker:'INVOICE DETAILS',html:invoiceDocument(r),actions:'<button class="button primary block" data-detail-download>Download invoice PDF</button>',editable:false,documentName:`invoice-${r.invoice_number}`});}
function viewReceipt(id){const r=state.payments.find(x=>x.id===id),job=project(r?.project_id);if(r)setupDetail('receipt',r,{title:r.payment_number||'Payment receipt',kicker:'RECEIVED PAYMENT',html:detailCard(`PAYMENT RECEIPT · ${r.payment_number||shortCode('RCP',r.id)}`,job?.name||'Project payment',money(r.amount),[['Business',state.business?.name||'Mughal Interior'],['Party',party(r.party_id)?.name],['Project',job?.name],['Date',date(r.payment_date)],['Received in',account(r.to_account_id)?.name],['Details',r.description],['Notes',r.notes]],true),actions:'<button class="button primary block" data-detail-download>Download payment PDF</button>',documentName:`payment-${r.payment_number||r.id}`});}
function viewLabourPerson(id){const r=labourer(id);if(r)setupDetail('labourPerson',r,{title:r.name,kicker:'LABOUR PERSON',html:detailCard('WORKFORCE RECORD',r.name,`${money(r.daily_wage_rate)} / day`,[['Record date',date(r.record_date||r.created_at)],['Date of joining',date(r.joining_date)],['Speciality',r.speciality],['Status',r.active===false?'Inactive':'Active']])});}
function viewLabourAssignment(id){const r=state.labourAssignments.find(x=>x.id===id),job=project(r?.project_id),worker=labourer(r?.labourer_id);if(r)setupDetail('labourAssignment',r,{title:worker?.name||'Labour assignment',kicker:'ASSIGNED LABOUR',html:detailCard(date(r.assignment_date),worker?.name||'Labour',money(r.amount??Number(r.days)*Number(r.daily_rate)),[['Project',job?projectLabel(job):'Project'],['Day worked',Number(r.days)===.5?'Half day':'Full day'],['Daily rate',money(r.daily_rate)],['Actual wage cost',money(r.amount??Number(r.days)*Number(r.daily_rate))],['Details',r.notes]]),editable:false,deletable:false});}
function viewMaterialAssignment(id){const r=state.materialMovements.find(x=>x.id===id),item=material(r?.material_id),job=project(r?.project_id);if(r)setupDetail('materialAssignment',r,{title:item?.name||'Material',kicker:'ASSIGNED MATERIAL',html:detailCard(date(r.movement_date),item?.name||'Material',money(Number(r.quantity)*Number(r.unit_cost)),[['Project',job?projectLabel(job):'Project'],['Quantity',`${qty(r.quantity)} ${item?.unit||'units'}`],['Purchase cost per unit',money(r.unit_cost)],['Total material cost',money(Number(r.quantity)*Number(r.unit_cost))],['Details',r.notes]]),editable:false,deletable:false});}
