function viewExpenseCharge(id){const r=state.entries.find(x=>x.id===id),job=project(r?.project_id),cat=expenseCategory(r?.expense_category_id);if(r)setupDetail('expenseCharge',r,{title:cat?.name||r.description,kicker:'CHARGED EXPENSE',html:detailCard(date(r.entry_date),cat?.name||r.description,money(r.amount),[['Project',job?projectLabel(job):'Project'],['Expense',cat?.name||r.description],['Details',r.notes]]),editable:false,deletable:false});}
function orderInvoiceDocument(order){const invoice=orderInvoice(order),lines=orderLines(order.id);return`<article class="detail-card pdf-document"><div class="detail-hero"><p>ORDER INVOICE · ${esc(invoice?.invoice_number||order.order_number)}</p><h3>${esc(order.customer_name)}</h3><div class="detail-amount">${money(order.amount)}</div></div>${detailRows([['Business',state.business?.name||'Mughal Interior'],['Invoice date',date(invoice?.invoice_date||order.order_date)],['Customer',order.customer_name],['Mobile number',order.customer_phone],['Order details',order.description]])}<div class="order-line-list">${lines.map(line=>`<div class="order-line-row"><div><b>${esc(line.item_name)}</b><small>${esc(line.details||'')} · ${qty(line.quantity)} × ${money(line.rate)}</small></div><strong>${money(line.amount??Number(line.quantity)*Number(line.rate))}</strong></div>`).join('')}</div>${detailRows([['Subtotal',money(order.subtotal??lines.reduce((sum,line)=>sum+Number(line.amount||0),0))],['Discount',`− ${money(order.discount)}`],['Grand total',money(order.amount)]])}</article>`;}
function viewOrderInvoice(id){const order=walkInOrder(id),invoice=order&&orderInvoice(order);if(order)setupDetail('orderInvoice',order,{title:invoice?.invoice_number||order.order_number,kicker:'ORDER INVOICE',html:orderInvoiceDocument(order),actions:'<button class="button primary block" data-detail-download>Download invoice PDF</button>',documentName:`order-invoice-${invoice?.invoice_number||order.order_number}`});}
