function viewOrderExpense(id){const r=state.walkInEntries.find(x=>x.id===id),order=walkInOrder(r?.walk_in_order_id),cat=expenseCategory(r?.expense_category_id);if(r)setupDetail('orderExpense',r,{title:cat?.name||r.description,kicker:'ORDER EXPENSE',html:detailCard(date(r.entry_date),cat?.name||r.description,money(r.amount),[['Order',order?orderLabel(order):'Order'],['Expense',cat?.name||r.description],['Details',r.notes]]),editable:false,deletable:false});}
