async function downloadCurrent(button){const node=$('#detailBody .pdf-document');if(!node)return;if(typeof html2pdf==='undefined')throw new Error('PDF download is unavailable. Refresh with an internet connection.');await working('Preparing your PDF…',button,()=>html2pdf().set({margin:[8,8,8,8],filename:`${safeName(state.detail?.documentName||'document')}.pdf`,image:{type:'jpeg',quality:.98},html2canvas:{scale:2,useCORS:true,backgroundColor:'#ffffff'},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},pagebreak:{mode:['css','legacy']}}).from(node).save());toast('PDF downloaded.');}
function openApproval(id){const r=project(id),choices=[];if(Number(r.price_with_material)>0)choices.push(['with_material','With material',r.price_with_material]);if(Number(r.price_without_material)>0)choices.push(['without_material','Without material',r.price_without_material]);if(!choices.length){toast('Add a quotation amount before approval.');return;}state.detail={type:'quote',id};$('#approvalChoices').innerHTML=choices.map((c,i)=>`<label class="approve-choice"><input type="radio" name="approvalType" value="${c[0]}" ${i===0?'checked':''}><span><b>${c[1]}</b><small>${money(c[2])}</small></span></label>`).join('');closeSheets();openSheet('#approvalSheet');}
function showLabourTab(name){$$('[data-labour-tab]').forEach(b=>b.classList.toggle('active',b.dataset.labourTab===name));$('#labourPersonsPanel').classList.toggle('active',name==='persons');$('#labourAssignmentsPanel').classList.toggle('active',name==='assignments');}
function showExpenseTab(name){$$('[data-expense-tab]').forEach(b=>b.classList.toggle('active',b.dataset.expenseTab===name));$('#expenseListPanel').classList.toggle('active',name==='list');$('#expenseChargesPanel').classList.toggle('active',name==='charges');}

$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const error=$('#loginError');error.classList.add('hidden');try{await working('Signing you in…',e.submitter,async()=>{await store.signIn($('#loginEmail').value,$('#loginPassword').value);await boot()})}catch(err){error.textContent=err.message;error.classList.remove('hidden')}});
$('#partyForm').addEventListener('submit',async e=>{e.preventDefault();const existing=party($('#partyId').value),row={id:existing?.id||$('#partyId').value,name:$('#partyName').value.trim(),phone:$('#partyPhone').value.trim()||null,party_type:existing?.party_type||'Individual',address:$('#partyAddress').value.trim()||null,notes:existing?.notes||null,created_at:existing?.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};try{await working(existing?'Updating party…':'Saving party…',e.submitter,async()=>{upsert(state.parties,await store.save('parties',row,Boolean(existing)));closeSheets();render();toast(existing?'Party updated.':'Party added.')})}catch{}});
