$('#quoteForm').addEventListener('submit',async e=>{e.preventDefault();const selected=project($('#quoteProjectId').value)||resolveProject($('#quoteProjectSearch').value);if(!selected){toast('Select a project from the search suggestions.');return}const withMaterial=$('#quoteWithMaterial').value===''?null:Number($('#quoteWithMaterial').value),withoutMaterial=$('#quoteWithoutMaterial').value===''?null:Number($('#quoteWithoutMaterial').value);if(!(withMaterial>0)&&!(withoutMaterial>0)){toast('Enter at least one quotation amount.');return}const row={id:selected.id,description:$('#quoteDetails').value.trim(),quote_date:$('#quoteDate').value,start_date:$('#quoteStart').value||null,expected_end_date:$('#quoteEnd').value||null,days_to_complete:$('#quoteDays').value===''?null:Number($('#quoteDays').value),pricing_mode:$('#quoteShowBoth').checked?'both':withMaterial>0?'with_material':'without_material',price_with_material:withMaterial,price_without_material:withoutMaterial,payment_terms:$('#quotePaymentTerms').value.trim()||null,notes:$('#quoteNotes').value.trim()||null,status:selected.status==='Approved'?'Approved':'Pending',quote_created:true,updated_at:new Date().toISOString()},download=e.submitter?.dataset.submitMode==='download';try{await working(download?'Saving quote and preparing PDF…':'Saving quote…',e.submitter,async()=>{const saved=await store.save('projects',row,true);upsert(state.projects,saved);closeSheets();render();viewQuote(saved.id);toast('Quote saved.');if(download)await downloadCurrent($('[data-detail-download]'))})}catch{}});
$('#approvalForm').addEventListener('submit',async e=>{e.preventDefault();const row=project(state.detail?.id),type=$('input[name="approvalType"]:checked')?.value;if(!row||!type)return;const amount=Number(type==='with_material'?row.price_with_material:row.price_without_material);try{await working('Approving quote and creating invoice…',e.submitter,async()=>{upsert(state.projects,await store.save('projects',{id:row.id,status:'Approved',contract_type:type,original_contract_amount:amount,updated_at:new Date().toISOString()},true));let invoice=state.invoices.find(x=>x.project_id===row.id);if(!invoice){invoice=await store.save('invoices',{id:uid(),project_id:row.id,walk_in_order_id:null,invoice_number:`MII-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`,invoice_date:today(),due_date:null,amount,notes:null,status:'Draft',created_at:new Date().toISOString(),updated_at:new Date().toISOString()},false);upsert(state.invoices,invoice)}closeSheets();render();viewQuote(row.id);toast('Quote approved and invoice created.')})}catch{}});
