$('#receiptForm').addEventListener('submit',async e=>{e.preventDefault();const existing=state.payments.find(r=>r.id===$('#receiptId').value),job=project(existing?.project_id||$('#receiptProject').value),invoice=state.invoices.find(r=>r.project_id===job?.id),input={payment_date:$('#receiptDate').value,to_account_id:$('#receiptAccount').value,amount:Number($('#receiptAmount').value),description:$('#receiptDetails').value.trim(),notes:null};try{await working(existing?'Updating payment…':'Saving payment…',e.submitter,async()=>{if(existing){if(cloud)await store.rpc('update_project_receipt',{p_payment_id:existing.id,p_payment_date:input.payment_date,p_to_account_id:input.to_account_id,p_amount:input.amount,p_description:input.description,p_notes:null});else{Object.assign(existing,input);const entry=state.entries.find(r=>r.payment_id===existing.id);if(entry)Object.assign(entry,{entry_date:input.payment_date,amount:input.amount,description:input.description})}}else if(cloud)await store.rpc('record_payment',{p_business_id:state.businessId,p_payment_type:'customer_receipt',p_payment_date:input.payment_date,p_from_account_id:null,p_to_account_id:input.to_account_id,p_party_id:job.party_id,p_supplier_id:null,p_project_id:job.id,p_walk_in_order_id:null,p_purchase_bill_id:null,p_invoice_id:invoice?.id||null,p_description:input.description,p_amount:input.amount,p_reference:null,p_notes:null});else{const payment={id:uid(),payment_number:`RCP-${Date.now().toString().slice(-7)}`,payment_type:'customer_receipt',party_id:job.party_id,project_id:job.id,invoice_id:invoice?.id||null,created_by:'demo',created_at:new Date().toISOString(),...input};state.payments.unshift(payment);state.entries.unshift({id:uid(),project_id:job.id,entry_type:'receipt',entry_date:input.payment_date,description:input.description,amount:input.amount,notes:null,payment_id:payment.id,created_at:new Date().toISOString()})}if(cloud)await store.load();store.persist();closeSheets();render();toast(existing?'Payment updated.':'Payment received.')})}catch{}});
