$('#orderInvoiceForm').addEventListener('submit',async e=>{e.preventDefault();const existing=walkInOrder($('#orderInvoiceOrderId').value),items=readOrderInvoiceLines(),discount=Number($('#orderInvoiceDiscount').value||0),subtotal=items.reduce((sum,line)=>sum+line.quantity*line.rate,0),total=subtotal-discount;if(items.some(line=>!line.order_item_id||!(line.quantity>0)||line.rate<0)){toast('Complete every invoice item, quantity and rate.');return}if(discount<0||discount>subtotal||total<=0){toast('Discount must be between zero and the subtotal.');return}const payload={p_invoice_date:$('#orderInvoiceDate').value,p_customer_name:$('#orderInvoiceCustomer').value.trim(),p_customer_phone:$('#orderInvoiceMobile').value.trim()||null,p_details:$('#orderInvoiceDetails').value.trim()||null,p_discount:discount,p_items:items};try{await working(existing?'Updating order invoice…':'Saving order invoice…',e.submitter,async()=>{let orderId=existing?.id;if(cloud){orderId=existing?await store.rpc('update_order_invoice',{p_order_id:existing.id,...payload}):await store.rpc('create_order_invoice',{p_business_id:state.businessId,...payload});await store.load()}else if(existing){Object.assign(existing,{customer_name:payload.p_customer_name,customer_phone:payload.p_customer_phone,description:payload.p_details||'Order invoice items',order_date:payload.p_invoice_date,subtotal,discount,amount:total});Object.assign(orderInvoice(existing),{invoice_date:payload.p_invoice_date,amount:total});state.orderInvoiceItems=state.orderInvoiceItems.filter(line=>line.walk_in_order_id!==existing.id);items.forEach((line,index)=>state.orderInvoiceItems.push({id:uid(),walk_in_order_id:existing.id,item_name:state.orderItems.find(item=>item.id===line.order_item_id)?.name,sort_order:index+1,amount:line.quantity*line.rate,...line}))}else{orderId=uid();const order={id:orderId,order_number:`MIW-${Date.now().toString().slice(-7)}`,customer_name:payload.p_customer_name,customer_phone:payload.p_customer_phone,title:'Order invoice',description:payload.p_details||'Order invoice items',order_date:payload.p_invoice_date,amount:total,subtotal,discount,status:'Pending',created_at:new Date().toISOString()};state.walkInOrders.unshift(order);state.invoices.unshift({id:uid(),walk_in_order_id:orderId,project_id:null,invoice_number:`MIO-${Date.now().toString().slice(-7)}`,invoice_date:payload.p_invoice_date,amount:total,status:'Draft'});items.forEach((line,index)=>state.orderInvoiceItems.push({id:uid(),walk_in_order_id:orderId,item_name:state.orderItems.find(item=>item.id===line.order_item_id)?.name,sort_order:index+1,amount:line.quantity*line.rate,...line}))}store.persist();closeSheets();render();viewOrderInvoice(orderId);toast(existing?'Order invoice updated.':'Order invoice saved.')})}catch{}});
$('#orderReceiptForm').addEventListener('submit',async e=>{e.preventDefault();const existing=state.payments.find(r=>r.id===$('#orderReceiptId').value),order=walkInOrder(existing?.walk_in_order_id||$('#orderReceiptOrder').value),input={payment_date:$('#orderReceiptDate').value,to_account_id:$('#orderReceiptAccount').value,amount:Number($('#orderReceiptAmount').value),description:$('#orderReceiptDetails').value.trim()};if(!existing&&input.amount>orderDue(order)){toast(`Receipt exceeds the order balance of ${money(Math.max(0,orderDue(order)))}.`);return}try{await working(existing?'Updating order receipt…':'Saving order receipt…',e.submitter,async()=>{if(existing){if(cloud)await store.rpc('update_order_receipt',{p_payment_id:existing.id,p_payment_date:input.payment_date,p_to_account_id:input.to_account_id,p_amount:input.amount,p_description:input.description,p_notes:null});else{Object.assign(existing,input);const entry=state.walkInEntries.find(r=>r.payment_id===existing.id);if(entry)Object.assign(entry,{entry_date:input.payment_date,amount:input.amount,description:input.description})}}else if(cloud)await store.rpc('record_payment',{p_business_id:state.businessId,p_payment_type:'customer_receipt',p_payment_date:input.payment_date,p_from_account_id:null,p_to_account_id:input.to_account_id,p_party_id:null,p_supplier_id:null,p_project_id:null,p_walk_in_order_id:order.id,p_purchase_bill_id:null,p_invoice_id:null,p_description:input.description,p_amount:input.amount,p_reference:null,p_notes:null});else{const payment={id:uid(),payment_number:`MIT-${Date.now().toString().slice(-7)}`,payment_type:'customer_receipt',walk_in_order_id:order.id,created_by:'demo',created_at:new Date().toISOString(),...input};state.payments.unshift(payment);state.walkInEntries.unshift({id:uid(),walk_in_order_id:order.id,entry_type:'receipt',entry_date:input.payment_date,description:input.description,amount:input.amount,payment_id:payment.id,created_at:new Date().toISOString()})}if(cloud)await store.load();store.persist();closeSheets();render();toast(existing?'Order receipt updated.':'Order payment received.')})}catch{}});
$('#orderExpenseChargeForm').addEventListener('submit',async e=>{e.preventDefault();const cat=expenseCategory($('#orderExpenseCategory').value),row={id:uid(),walk_in_order_id:$('#orderExpenseOrder').value,entry_type:'expense',entry_date:$('#orderExpenseDate').value,description:cat.name,amount:Number($('#orderExpenseAmount').value),notes:$('#orderExpenseDetails').value.trim()||null,expense_category_id:cat.id,created_at:new Date().toISOString()};try{await working('Assigning order expense…',e.submitter,async()=>{upsert(state.walkInEntries,await store.save('walk_in_order_entries',row));closeSheets();render();showOrderExpenseTab('charges');toast('Expense assigned to order.')})}catch{}});
$('#orderMaterialForm').addEventListener('submit',async e=>{e.preventDefault();const item=material($('#orderMaterialItem').value),orderId=$('#orderMaterialOrder').value,mode=$('#orderMaterialMode').value,metric=materialMetrics(item),quantity=Number($('#orderMaterialQuantity').value),available=mode==='return'?orderReturnable(orderId,item.id):metric.stock;if(quantity>available){toast(`${mode==='return'?'Only':'Stock only'} ${qty(available)} ${item.unit} ${mode==='return'?'can be returned.':'is available.'}`);return}const row={id:uid(),material_id:item.id,project_id:null,walk_in_order_id:orderId,movement_type:mode==='return'?'walk_in_return':'walk_in_issue',movement_date:$('#orderMaterialDate').value,quantity,unit_cost:metric.unitCost,supplier_name:null,reference:null,notes:$('#orderMaterialDetails').value.trim()||null,created_at:new Date().toISOString()};try{await working(mode==='return'?'Returning material…':'Assigning material…',e.submitter,async()=>{const saved=await store.save('material_movements',row);if(cloud)await store.load();else{state.materialMovements.unshift(saved);state.walkInEntries.unshift({id:uid(),walk_in_order_id:orderId,entry_type:mode==='return'?'material_return':'material',entry_date:row.movement_date,description:`${mode==='return'?'Material returned':'Material'}: ${item.name}`,amount:quantity*metric.unitCost,notes:row.notes})}store.persist();closeSheets();render();toast(mode==='return'?'Material returned to stock.':'Material assigned to order.')})}catch{}});
$('#orderLabourForm').addEventListener('submit',async e=>{e.preventDefault();const days=Number($('#orderLabourDay').value),rate=Number($('#orderLabourRate').value),row={id:uid(),labourer_id:$('#orderLabourPerson').value,project_id:null,walk_in_order_id:$('#orderLabourOrder').value,assignment_date:$('#orderLabourDate').value,days,daily_rate:rate,notes:$('#orderLabourDetails').value.trim()||null,created_at:new Date().toISOString()};try{await working('Assigning order labour…',e.submitter,async()=>{const saved=await store.save('labour_assignments',row);if(cloud)await store.load();else{saved.amount=days*rate;state.labourAssignments.unshift(saved);state.walkInEntries.unshift({id:uid(),walk_in_order_id:row.walk_in_order_id,entry_type:'labour',entry_date:row.assignment_date,description:`Labour: ${labourer(row.labourer_id)?.name}`,amount:days*rate,notes:row.notes})}store.persist();closeSheets();render();showOrderLabourTab('assignments');toast('Labour assigned to order.')})}catch{}});
$('#orderItemForm').addEventListener('submit',async e=>{e.preventDefault();const existing=state.orderItems.find(r=>r.id===$('#orderItemId').value),row={id:existing?.id||uid(),name:$('#orderItemName').value.trim(),details:$('#orderItemDetails').value.trim()||null,active:true,created_at:existing?.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};try{await working(existing?'Updating item…':'Saving item…',e.submitter,async()=>{upsert(state.orderItems,await store.save('order_items',row,Boolean(existing)));closeSheets();render();toast(existing?'Item updated.':'Invoice item added.')})}catch{}});

async function deleteDetail(button){const {type,id}=state.detail||{};if(!type)return;const messages={party:'Delete this party? This cannot be undone.',project:'Delete this project? This cannot be undone.',quote:'Delete this quote? The project record will remain.',invoice:'Delete this invoice? The quote will return to Pending.',receipt:'Delete this received payment? Its project receipt entry will also be removed.',labourPerson:'Delete this labour person? This cannot be undone.',expenseCategory:'Delete this expense type? This cannot be undone.',orderInvoice:'Delete this order invoice? This is only allowed before receipts, expenses, material or labour are recorded.',orderReceipt:'Delete this received payment? Its order receipt entry will also be removed.',orderItem:'Delete this invoice item? Existing saved invoices will keep their item details.'};if(!confirm(messages[type]||'Delete this record? This cannot be undone.'))return;try{await working(`Deleting ${type}…`,button,async()=>{if(type==='party'){await store.remove('parties',id);state.parties=state.parties.filter(r=>r.id!==id)}if(type==='project'){const row=project(id);if(row.quote_created||state.entries.some(e=>e.project_id===id)||state.invoices.some(i=>i.project_id===id))throw new Error('Delete its quote, invoice and project activity before deleting this project.');await store.remove('projects',id);state.projects=state.projects.filter(r=>r.id!==id)}if(type==='quote'){const row=project(id);if(row.status==='Approved')throw new Error('Delete the invoice first before deleting an approved quote.');upsert(state.projects,await store.save('projects',{id,description:null,start_date:null,expected_end_date:null,days_to_complete:null,price_with_material:null,price_without_material:null,payment_terms:null,notes:null,pricing_mode:'with_material',quote_created:false,status:'Pending',updated_at:new Date().toISOString()},true))}if(type==='invoice'){const invoice=state.invoices.find(r=>r.id===id);await store.remove('invoices',id);state.invoices=state.invoices.filter(r=>r.id!==id);const job=project(invoice.project_id);if(job)upsert(state.projects,await store.save('projects',{id:job.id,status:'Pending',original_contract_amount:0,updated_at:new Date().toISOString()},true))}if(type==='receipt'){if(cloud)await store.rpc('delete_project_receipt',{p_payment_id:id});state.payments=state.payments.filter(r=>r.id!==id);state.entries=state.entries.filter(r=>r.payment_id!==id)}if(type==='labourPerson'){await store.remove('labourers',id);state.labourers=state.labourers.filter(r=>r.id!==id)}if(type==='expenseCategory'){await store.remove('expense_categories',id);state.expenseCategories=state.expenseCategories.filter(r=>r.id!==id)}if(type==='orderInvoice'){if(cloud)await store.rpc('delete_order_invoice',{p_order_id:id});else{const hasActivity=state.walkInEntries.some(r=>r.walk_in_order_id===id)||state.materialMovements.some(r=>r.walk_in_order_id===id)||state.labourAssignments.some(r=>r.walk_in_order_id===id);if(hasActivity)throw new Error('Delete order activity before deleting this invoice.');state.walkInOrders=state.walkInOrders.filter(r=>r.id!==id);state.invoices=state.invoices.filter(r=>r.walk_in_order_id!==id);state.orderInvoiceItems=state.orderInvoiceItems.filter(r=>r.walk_in_order_id!==id)}}if(type==='orderReceipt'){if(cloud)await store.rpc('delete_order_receipt',{p_payment_id:id});state.payments=state.payments.filter(r=>r.id!==id);state.walkInEntries=state.walkInEntries.filter(r=>r.payment_id!==id)}if(type==='orderItem'){await store.remove('order_items',id);state.orderItems=state.orderItems.filter(r=>r.id!==id)}if(cloud&&['orderInvoice','orderReceipt'].includes(type))await store.load();store.persist();closeSheets();render();toast('Record deleted.')})}catch{}}
const viewHandlers={'party':viewParty,'project':viewProject,'quote':viewQuote,'invoice':viewInvoice,'receipt':viewReceipt,'labour-person':viewLabourPerson,'labour-assignment':viewLabourAssignment,'material-assignment':viewMaterialAssignment,'expense-category':viewExpenseCategory,'expense-charge':viewExpenseCharge,'order-invoice':viewOrderInvoice,'order-receipt':viewOrderReceipt,'order-expense':viewOrderExpense,'order-material':viewOrderMaterial,'order-labour':viewOrderLabour,'order-item':viewOrderItem};
document.addEventListener('click',async e=>{
  const routeButton=e.target.closest('[data-route]');if(routeButton)route(routeButton.dataset.route);
  const orderRouteButton=e.target.closest('[data-order-route]');if(orderRouteButton)route(orderRouteButton.dataset.orderRoute);
  const tabButton=e.target.closest('[data-tab]');if(tabButton)tab(tabButton.dataset.tab);
  if(e.target.closest('[data-close]')||e.target.id==='backdrop')closeSheets();
  const action=e.target.closest('[data-action]')?.dataset.action;
  ({'add-party':openParty,'add-project':openProject,'add-quote':openQuote,'scope-change':openScope,'add-receipt':openReceipt,'add-labour-person':openLabourPerson,'assign-labour':openLabourAssignment,'assign-material':openMaterialAssignment,'add-expense':openExpenseCategory,'charge-expense':openExpenseCharge,'add-order-invoice':openOrderInvoice,'add-order-receipt':openOrderReceipt,'charge-order-expense':openOrderExpense,'assign-order-material':()=>openOrderMaterial('assign'),'return-order-material':()=>openOrderMaterial('return'),'assign-order-labour':openOrderLabour,'add-order-item':openOrderItem}[action]||(()=>{}))();
  const projectAction=e.target.closest('[data-project-action]');if(projectAction)route({receipt:'receipts',labour:'labour',material:'materials',expense:'expenses'}[projectAction.dataset.projectAction]);
  const labourTab=e.target.closest('[data-labour-tab]');if(labourTab)showLabourTab(labourTab.dataset.labourTab);
  const expenseTab=e.target.closest('[data-expense-tab]');if(expenseTab)showExpenseTab(expenseTab.dataset.expenseTab);
  const orderExpenseTab=e.target.closest('[data-order-expense-tab]');if(orderExpenseTab)showOrderExpenseTab(orderExpenseTab.dataset.orderExpenseTab);
  const orderLabourTab=e.target.closest('[data-order-labour-tab]');if(orderLabourTab)showOrderLabourTab(orderLabourTab.dataset.orderLabourTab);
  const removeOrderLine=e.target.closest('[data-remove-order-line]');if(removeOrderLine){const lines=$$('.invoice-line',$('#orderInvoiceLines'));if(lines.length===1)toast('An invoice needs at least one item.');else{removeOrderLine.closest('.invoice-line').remove();recalcOrderInvoice();}}
  for(const [name,handler] of Object.entries(viewHandlers)){const button=e.target.closest(`[data-view-${name}]`);if(button){handler(button.getAttribute(`data-view-${name}`));break}}
  const approve=e.target.closest('[data-approve-quote]');if(approve)openApproval(approve.dataset.approveQuote);
  const download=e.target.closest('[data-detail-download]');if(download)try{await downloadCurrent(download)}catch{}
  const listDownload=e.target.closest('[data-download-invoice]');if(listDownload){viewInvoice(listDownload.dataset.downloadInvoice);try{await downloadCurrent($('[data-detail-download]'))}catch{}}
  if(e.target.id==='detailDelete')await deleteDetail(e.target);
  if(e.target.id==='detailEdit'){const d=state.detail;closeSheets();if(d.type==='party')openParty(d.id);if(d.type==='project')openProject(d.id);if(d.type==='quote')openQuote(d.id);if(d.type==='receipt')openReceipt(d.id);if(d.type==='labourPerson')openLabourPerson(d.id);if(d.type==='expenseCategory')openExpenseCategory(d.id);if(d.type==='orderInvoice')openOrderInvoice(d.id);if(d.type==='orderReceipt')openOrderReceipt(d.id);if(d.type==='orderItem')openOrderItem(d.id)}
});
['partySearch','projectSearch','quoteSearch','invoiceSearch','receiptSearch','materialAssignmentSearch','orderInvoiceSearch','orderReceiptSearch','orderMaterialSearch','orderItemSearch'].forEach(id=>$('#'+id).addEventListener('input',render));
$('#quoteStart').addEventListener('change',setQuoteDays);$('#quoteEnd').addEventListener('change',setQuoteDays);
$('#labourAssignmentPerson').addEventListener('change',updateLabourCost);$('#labourDayType').addEventListener('change',updateLabourCost);
$('#materialAssignmentMaterial').addEventListener('change',updateMaterialCost);$('#materialAssignmentQuantity').addEventListener('input',updateMaterialCost);
$('#addOrderInvoiceLine').addEventListener('click',()=>addOrderInvoiceLine());
$('#orderInvoiceMobile').addEventListener('input',autofillOrderCustomer);$('#orderInvoiceMobile').addEventListener('change',autofillOrderCustomer);
$('#orderInvoiceDiscount').addEventListener('input',recalcOrderInvoice);
$('#orderInvoiceLines').addEventListener('input',e=>{if(e.target.matches('[data-order-line-qty],[data-order-line-rate]'))recalcOrderInvoice()});
$('#orderInvoiceLines').addEventListener('change',e=>{if(e.target.matches('[data-order-line-item]')){const line=e.target.closest('.invoice-line'),item=state.orderItems.find(r=>r.id===e.target.value),details=$('[data-order-line-details]',line);if(item&&!details.value)details.value=item.details||'';recalcOrderInvoice();}});
['orderMaterialOrder','orderMaterialItem'].forEach(id=>$('#'+id).addEventListener('change',updateOrderMaterialCost));$('#orderMaterialQuantity').addEventListener('input',updateOrderMaterialCost);
$('#orderLabourPerson').addEventListener('change',updateOrderLabourCost);$('#orderLabourDay').addEventListener('change',updateOrderLabourCost);
$('#logoutBtn').addEventListener('click',()=>{if(confirm('Sign out of Mughal Interior Accounts?'))logout()});
function logout(show=true){localStorage.removeItem('mi_mobile_session');state.token=null;state.userId=null;$('#app').classList.add('hidden');$('#loginScreen').classList.remove('hidden');if(show)toast('Signed out.');}
async function boot(){if(cloud&&!state.token){const saved=JSON.parse(localStorage.getItem('mi_mobile_session')||'null');if(!saved){$('#loginScreen').classList.remove('hidden');return}state.token=saved.token;state.userId=saved.userId}try{await store.load();$('#loginScreen').classList.add('hidden');$('#app').classList.remove('hidden');render();tab('projectsHub')}catch(error){if(cloud){logout(false);$('#loginError').textContent=error.message;$('#loginError').classList.remove('hidden')}else toast(error.message)}}
boot();
